#!/usr/bin/env python

from patsy import dmatrix, build_design_matrices, PatsyError
from patsy.origin import Origin

def test_origin_combining():
    # Test that when there's a mismatch, both origins are included in the error
    try:
        # Create initial design matrix
        data1 = {"X": [0, 1, 2, 3], "Y": [1, 2, 3, 4]}
        formula = "C(X) + Y"
        design_info = dmatrix(formula, data1)

        # Try to build with incompatible data (different levels for X)
        data2 = {"X": [0, 0, 1, 2, 3, 3, 4], "Y": [1, 2, 3, 4, 5, 6, 7]}
        build_design_matrices([design_info.design_info], data2)

        # If we reach here, the test failed
        print("ERROR: Expected PatsyError was not raised")
        return False
    except PatsyError as e:
        # Check that the error includes origin information
        print("SUCCESS: PatsyError was raised as expected")
        print("Error message:", str(e))
        if e.origin is not None:
            print("Combined origin information is present")
            return True
        else:
            print("ERROR: No origin information in error")
            return False
    except Exception as e:
        print("ERROR: Unexpected exception:", type(e).__name__, str(e))
        return False

if __name__ == "__main__":
    success = test_origin_combining()
    if success:
        print("\nTest PASSED")
    else:
        print("\nTest FAILED")
EOF
